algorithms.pseudocode:
for region in strategy.regions:
  ensure_pods(canary=k, baseline=k)
  for step in strategy.steps:
    if not policy.check(rel, step): pause(rel, reason); wait_until_ok()
    traffic.set_weights(stable=100-2*step.w, baseline=step.w, canary=step.w)
    for t in every(1 min, until=step.bake):
      r = judge.run(rel, window=last(step.bake_so_far))
      if r.critical_fail: return abort(rel)
    r = judge.run(rel, window=step.bake)
    if r.verdict == FAIL: return abort(rel)
    if r.verdict == MARGINAL and not extended: extend(step); continue
    if r.verdict == NODATA: pause(rel)
  promote_region(region); sleep(strategy.region_bake)

abort(rel): traffic.set_weights(stable=100, 0, 0); scale(canary, 0); notify()

bucket = murmur3(user_id + service_salt) % 10000
if bucket < canary_w * 100: route(canary)
elif bucket < (canary_w + baseline_w) * 100: route(baseline)
else: route(stable)
# changing salt per release avoids always exposing the same users to canaries
